`define COMMON_CLK_EN_PC_86cf6e4e58e3
`define BRAM_AUTO_86cf6e4e58e3
module axi_width_converter_top_86cf6e4e58e3 #
  (
   parameter integer AL_AXI_PROTOCOL                      = 0,  // (0=AXI4, 1=AXI3, 2=AXI4LITE).
   parameter integer AL_US_AXI_ID_WIDTH                   = 8,  // Range: 1 - 32.
   parameter integer AL_AXI_ADDR_WIDTH                    = 32, // Range (AXI4, AXI3): 12 - 64.
                                                                // Range (AXI4LITE): 1 - 64.
   parameter integer AL_US_AXI_DATA_WIDTH                 = 512,
                                                                // Range (AXI4, AXI3): 32, 64, 128, 256, 512, 1024.
                                                                // Range (AXILITE): 32, 64.
   parameter integer AL_DS_AXI_DATA_WIDTH                 = 256,
                                                                                                                                // Range (AXI4, AXI3): 32, 64, 128, 256, 512, 1024.
                                                                // Range (AXILITE): 32, 64.
                                                                // S_DATA_WIDTH = M_DATA_WIDTH allowed only when AXI4/AXI3 and PACKING_LEVEL=2.
   parameter integer AL_AXI_SUPPORTS_WRITE                = 1,
   parameter integer AL_AXI_SUPPORTS_READ                 = 1,
   parameter integer AL_MAX_SPLIT_BEATS                   = 256, // Range:16, 256.
   parameter integer AL_PACKING_LEVEL                     = 2
                                                                 // Upsizer packing mode.
                                                                 // 0 = Never pack (expander only); packing logic is omitted.
                                                                 // 1 = Pack only when CACHE[1] (Modifiable) is high.
                                                                 // 2 = Always pack, regardless of sub-size transaction or Modifiable bit.
                                                                 //     (Required when used as helper-core by mem-con. Same size AXI interfaces
                                                                 //      should only be used when always packing)
   )
  (
    
   input  wire                                                          aclk,
   input  wire                                                          aresetn,

   input  wire [AL_US_AXI_ID_WIDTH-1:0]     us_awid,
   input  wire [AL_AXI_ADDR_WIDTH-1:0]      us_awaddr,
   input  wire [((AL_AXI_PROTOCOL == 1) ? 4 : 8)-1:0] us_awlen,
   input  wire [3-1:0]                      us_awsize,
   input  wire [2-1:0]                      us_awburst,
   input  wire [((AL_AXI_PROTOCOL == 1) ? 2 : 1)-1:0] us_awlock,
   input  wire [4-1:0]                      us_awcache,
   input  wire [3-1:0]                      us_awprot,
   input  wire [4-1:0]                      us_awregion,
   input  wire [4-1:0]                      us_awqos,
   input  wire                              us_awvalid,
   output wire                              us_awready,
   input  wire [AL_US_AXI_DATA_WIDTH-1:0]   us_wdata,
   input  wire [AL_US_AXI_DATA_WIDTH/8-1:0] us_wstrb,
   input  wire                              us_wlast,
   input  wire                              us_wvalid,
   output wire                              us_wready,
   output wire [AL_US_AXI_ID_WIDTH-1:0]     us_bid,
   output wire [2-1:0]                      us_bresp,
   output wire                              us_bvalid,
   input  wire                              us_bready,
   input  wire [AL_US_AXI_ID_WIDTH-1:0]     us_arid,
   input  wire [AL_AXI_ADDR_WIDTH-1:0]      us_araddr,
   input  wire [((AL_AXI_PROTOCOL == 1) ? 4 : 8)-1:0] us_arlen,
   input  wire [3-1:0]                      us_arsize,
   input  wire [2-1:0]                      us_arburst,
   input  wire [((AL_AXI_PROTOCOL == 1) ? 2 : 1)-1:0] us_arlock,
   input  wire [4-1:0]                      us_arcache,
   input  wire [3-1:0]                      us_arprot,
   input  wire [4-1:0]                      us_arregion,
   input  wire [4-1:0]                      us_arqos,
   input  wire                              us_arvalid,
   output wire                              us_arready,
   output wire [AL_US_AXI_ID_WIDTH-1:0]     us_rid,
   output wire [AL_US_AXI_DATA_WIDTH-1:0]   us_rdata,
   output wire [2-1:0]                      us_rresp,
   output wire                              us_rlast,
   output wire                              us_rvalid,
   input  wire                              us_rready,

   output wire [AL_AXI_ADDR_WIDTH-1:0]      ds_awaddr,
   output wire [((AL_AXI_PROTOCOL == 1) ? 4 : 8)-1:0] ds_awlen,
   output wire [3-1:0]                      ds_awsize,
   output wire [2-1:0]                      ds_awburst,
   output wire [((AL_AXI_PROTOCOL == 1) ? 2 : 1)-1:0] ds_awlock,
   output wire [4-1:0]                      ds_awcache,
   output wire [3-1:0]                      ds_awprot,
   output wire [4-1:0]                      ds_awregion,
   output wire [4-1:0]                      ds_awqos,
   output wire                              ds_awvalid,
   input  wire                              ds_awready,
   output wire [AL_DS_AXI_DATA_WIDTH-1:0]   ds_wdata,
   output wire [AL_DS_AXI_DATA_WIDTH/8-1:0] ds_wstrb,
   output wire                              ds_wlast,
   output wire                              ds_wvalid,
   input  wire                              ds_wready,
   input  wire [2-1:0]                      ds_bresp,
   input  wire                              ds_bvalid,
   output wire                              ds_bready,
   output wire [AL_AXI_ADDR_WIDTH-1:0]      ds_araddr,
   output wire [((AL_AXI_PROTOCOL == 1) ? 4 : 8)-1:0] ds_arlen,
   output wire [3-1:0]                      ds_arsize,
   output wire [2-1:0]                      ds_arburst,
   output wire [((AL_AXI_PROTOCOL == 1) ? 2 : 1)-1:0] ds_arlock,
   output wire [4-1:0]                      ds_arcache,
   output wire [3-1:0]                      ds_arprot,
   output wire [4-1:0]                      ds_arregion,
   output wire [4-1:0]                      ds_arqos,
   output wire                              ds_arvalid,
   input  wire                              ds_arready,
   input  wire [AL_DS_AXI_DATA_WIDTH-1:0]   ds_rdata,
   input  wire [2-1:0]                      ds_rresp,
   input  wire                              ds_rlast,
   input  wire                              ds_rvalid,
   output wire                              ds_rready
   );

